    89	    const validator = useCallback(
    90	        (values: FormOnyxValues<typeof ONYXKEYS.FORMS.HOME_ADDRESS_FORM>): Errors => {
    91	            const errors: Errors & {
    92	                zipPostCode?: string | string[];
    93	            } = {};
    94	            const requiredFields = ['addressLine1', 'city', 'country', 'state'] as const;
    95	
    96	            // Check "State" dropdown is a valid state if selected Country is USA
    97	            if (values.country === CONST.COUNTRY.US && !values.state) {
    98	                errors.state = translate('common.error.fieldRequired');
    99	            }
   100	
   101	            // Add "Field required" errors if any required field is empty
   102	            requiredFields.forEach((fieldKey) => {
   103	                const fieldValue = values[fieldKey] ?? '';
   104	                if (isRequiredFulfilled(fieldValue)) {
   105	                    return;
   106	                }
   107	
   108	                errors[fieldKey] = translate('common.error.fieldRequired');
   109	            });
