   188	            <InputWrapper
   189	                InputComponent={TextInput}
   190	                inputID={INPUT_IDS.ADDRESS_LINE_2}
   191	                label={translate('common.addressLine', {lineNumber: 2})}
   192	                aria-label={translate('common.addressLine', {lineNumber: 2})}
   193	                role={CONST.ROLE.PRESENTATION}
   194	                defaultValue={street2}
   195	                spellCheck={false}
   196	                shouldSaveDraft={shouldSaveDraft}
   197	            />
   198	            <View style={styles.formSpaceVertical} />
   199	            <View style={styles.mhn5}>
   200	                <InputWrapper
   201	                    InputComponent={CountrySelector}
   202	                    inputID={INPUT_IDS.COUNTRY}
   203	                    value={country}
   204	                    onValueChange={onAddressChanged}
   205	                    shouldSaveDraft={shouldSaveDraft}
