   220	                <InputWrapper
   221	                    InputComponent={TextInput}
   222	                    inputID={INPUT_IDS.STATE}
   223	                    label={translate('common.stateOrProvince')}
   224	                    aria-label={translate('common.stateOrProvince')}
   225	                    role={CONST.ROLE.PRESENTATION}
   226	                    value={state}
   227	                    spellCheck={false}
   228	                    onValueChange={onAddressChanged}
   229	                    shouldSaveDraft={shouldSaveDraft}
