   233	            <InputWrapper
   234	                InputComponent={TextInput}
   235	                inputID={INPUT_IDS.CITY}
   236	                label={translate('common.city')}
   237	                aria-label={translate('common.city')}
   238	                role={CONST.ROLE.PRESENTATION}
   239	                defaultValue={city}
